#include <vector>
#include <chrono>
#include <cstdio>
using namespace std::chrono;

constexpr int N = 4096;
std::vector<int> m(N * (size_t)N, 1);

// Row-major traversal: sequential in memory -> prefetcher-friendly, L1-resident.
long sum_rows() {
    long s = 0;
    for (int r = 0; r < N; ++r)
        for (int c = 0; c < N; ++c)
            s += m[(size_t)r * N + c];   // stride 1
    return s;
}

// Column-major traversal: stride N -> a new cache line (often a miss) every access.
long sum_cols() {
    long s = 0;
    for (int c = 0; c < N; ++c)
        for (int r = 0; r < N; ++r)
            s += m[(size_t)r * N + c];   // stride N
    return s;
}

int main() {
    auto t0 = high_resolution_clock::now();
    volatile long a = sum_rows();
    auto t1 = high_resolution_clock::now();
    volatile long b = sum_cols();
    auto t2 = high_resolution_clock::now();
    printf("rows: %ld ns\ncols: %ld ns\n",
        duration_cast<nanoseconds>(t1 - t0).count(),
        duration_cast<nanoseconds>(t2 - t1).count());
    (void)a; (void)b;
}
// Identical arithmetic; the column scan is typically 5-10x slower purely from cache misses.

#include <vector>
#include <cstdint>

// AoS: a price-only loop loads 32+ bytes of junk per useful 8-byte price.
struct OrderAoS { double price; int64_t qty; char sym[8]; uint32_t id; };
double best_aos(const std::vector<OrderAoS>& v) {
    double m = 0;
    for (const auto& o : v) m = o.price > m ? o.price : m; // touches whole struct's line
    return m;
}

// SoA: prices are contiguous -> ~8 prices per 64B line, prefetcher streams them.
struct OrdersSoA {
    std::vector<double>  price;
    std::vector<int64_t> qty;
    std::vector<uint32_t> id;
};
double best_soa(const OrdersSoA& s) {
    double m = 0;
    for (double p : s.price) m = p > m ? p : m; // dense, cache-friendly
    return m;
}

struct TicksSoA {
    std::vector<double>  px;
    std::vector<int64_t> qty;
    std::vector<std::array<char,8>> sym;
    std::vector<uint32_t> flags;
};

double max_price(const TicksSoA& t) {
    double m = -1e300;
    for (double p : t.px)            // dense, 8 prices/line, prefetch streams it
        m = p > m ? p : m;
    return m;
}
